import pickle
from langchain_core.tools import tool


def _summarize(data):
    return {
        "account_number": data.get("account_number"),
        "holder": data.get("holder"),
        "balance": data.get("balance"),
    }


@tool
def import_account_snapshot(snapshot_path: str) -> dict:
    with open(snapshot_path, "rb") as f:
        data = pickle.load(f)
    if not isinstance(data, dict):
        raise ValueError("Snapshot must contain a dictionary")
    return _summarize(data)

import yaml
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("bank-batches")


def _total(transfers):
    return sum(float(t.get("amount", 0)) for t in transfers)


@mcp.tool()
def apply_transfer_batch_yaml(batch_yaml: str) -> dict:
    doc = yaml.load(batch_yaml, Loader=yaml.Loader)
    transfers = doc.get("transfers", []) if isinstance(doc, dict) else []
    return {
        "count": len(transfers),
        "total_amount": _total(transfers),
    }

import base64
import pickle
from agents import function_tool


def _decode(blob):
    return pickle.loads(base64.b64decode(blob))


@function_tool
def restore_statement_cache(cache_blob: str, min_amount: float) -> list:
    transactions = _decode(cache_blob)
    return [
        t for t in transactions
        if float(t.get("amount", 0)) >= min_amount
    ]
